import{_ as a,o as t,c as r,ag as o}from"./chunks/framework.CZxGLIO_.js";const h=JSON.parse('{"title":"Backup, upgrades and recovery","description":"Back up GooseForum completely, upgrade the binary and database, and verify recovery.","frontmatter":{"title":"Backup, upgrades and recovery","description":"Back up GooseForum completely, upgrade the binary and database, and verify recovery."},"headers":[],"relativePath":"en/docs/gooseforum/maintenance/index.md","filePath":"en/docs/gooseforum/maintenance/index.md"}'),s={name:"en/docs/gooseforum/maintenance/index.md"};function n(i,e,d,c,l,p){return t(),r("div",null,[...e[0]||(e[0]=[o(`<h1 id="backup-upgrades-and-recovery" tabindex="-1">Backup, upgrades and recovery <a class="header-anchor" href="#backup-upgrades-and-recovery" aria-label="Permalink to &quot;Backup, upgrades and recovery&quot;">​</a></h1><p>A useful backup restores both site data and runtime configuration. A release archive alone, or a SQLite file alone, does not cover every deployment.</p><h2 id="backup-scope" tabindex="-1">Backup scope <a class="header-anchor" href="#backup-scope" aria-label="Permalink to &quot;Backup scope&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Reason</th></tr></thead><tbody><tr><td><code>config.toml</code></td><td>Database connections, storage settings and the original system secret needed for encrypted MFA data</td></tr><tr><td>Entire <code>storage/</code> directory</td><td>Default SQLite database, logs and local backups; actual contents depend on configuration</td></tr><tr><td>External MySQL / PostgreSQL</td><td>Not included in local storage; use the database&#39;s own backup tools</td></tr><tr><td>S3 objects and configuration</td><td>Database backups do not include bucket objects</td></tr><tr><td>Current binary version and commit</td><td>Recreate an environment compatible with the data</td></tr></tbody></table><p>Copy backups to independent storage and restrict access. They may contain credentials, personal information and private attachments.</p><h2 id="automatic-sqlite-backups" tabindex="-1">Automatic SQLite backups <a class="header-anchor" href="#automatic-sqlite-backups" aria-label="Permalink to &quot;Automatic SQLite backups&quot;">​</a></h2><p>Check the existing <code>[db]</code> section:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">backupSqlite = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">backupDir = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;./storage/databasebackup/&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">keep = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">7</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">spec = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0 3 * * *&quot;</span></span></code></pre></div><p>This enables SQLite backups, keeps seven files and schedules them for 03:00 daily. Verify the process timezone, writable destination, free space, actual output and logs. It does not back up system secrets, external databases or S3 objects, and a backup on the same machine cannot protect against loss of that machine.</p><p>For manual SQLite file copying, stop the service first. Copying only a live database&#39;s main file can omit committed data still in its WAL.</p><h2 id="upgrade-procedure" tabindex="-1">Upgrade procedure <a class="header-anchor" href="#upgrade-procedure" aria-label="Permalink to &quot;Upgrade procedure&quot;">​</a></h2><ol><li>Read the target <a href="https://github.com/leancodebox/GooseForum/releases" target="_blank" rel="noreferrer">release notes</a>. Record the current version, working directory and database type.</li><li>Pause writes and stop the service. With the documented systemd setup, use <code>sudo systemctl stop gooseforum</code>.</li><li>Back up configuration, databases and storage; retain the old binary. Use a consistent backup method for external databases.</li><li>Extract and verify the release in a temporary directory. Replace the program while retaining configuration, secrets and data.</li><li>Check <code>[db].migration</code>. With migrations enabled, startup applies schema changes; alternatively run <code>./GooseForum migrate</code> from the same working directory.</li><li>Start the service and inspect logs. Verify login, categories, topics, replies, attachments and administration.</li></ol><p>Preserve migration errors rather than deleting accounts or databases to force startup. Historical usernames or emails that collide after normalization can prevent unique-index creation and require a data review.</p><h2 id="recovery-and-rollback" tabindex="-1">Recovery and rollback <a class="header-anchor" href="#recovery-and-rollback" aria-label="Permalink to &quot;Recovery and rollback&quot;">​</a></h2><p>First rehearse recovery in an isolated directory or machine, avoiding real email sends or writes to production object storage. Stop the target service, restore configuration, databases and files from a consistent backup point, fix permissions and paths, then run the matching version.</p><p>After a schema migration, <strong>restoring the old binary alone is not a guaranteed rollback</strong>. Restore the pre-upgrade database and related files with the retained old program. An older snapshot loses newer writes; choose the recovery point deliberately.</p><p>Verify account login and MFA, old topics and images, new posts and replies, admin permissions, email and new backup creation. Record the version and time required for a successful recovery exercise.</p><h2 id="old-content-after-an-update" tabindex="-1">Old content after an update <a class="header-anchor" href="#old-content-after-an-update" aria-label="Permalink to &quot;Old content after an update&quot;">​</a></h2><p>The main site and admin use <code>/api/forum/status</code> to detect deployment changes and offer a refresh without automatically discarding unsaved content. Frontend assets are embedded: source builds must build the frontend before the Go binary. If refreshing fails, inspect proxy caching, asset requests and the executable actually running.</p><hr><p>Sources checked on 2026-11-15：<a href="https://github.com/leancodebox/GooseForum/blob/3044207dea0a9fd5c878406eb0aa094f5798f0ff/docs/configuration.md" target="_blank" rel="noreferrer">Backup configuration</a> · <a href="https://github.com/leancodebox/GooseForum/blob/3044207dea0a9fd5c878406eb0aa094f5798f0ff/README_ZH.md" target="_blank" rel="noreferrer">Migration command</a> · <a href="https://github.com/leancodebox/GooseForum/blob/3044207dea0a9fd5c878406eb0aa094f5798f0ff/docs/registration-controls.md" target="_blank" rel="noreferrer">Identity migrations</a> · <a href="https://github.com/leancodebox/GooseForum/blob/3044207dea0a9fd5c878406eb0aa094f5798f0ff/docs/site-status.md" target="_blank" rel="noreferrer">Update detection</a>。</p>`,21)])])}const b=a(s,[["render",n]]);export{h as __pageData,b as default};
